SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
CROSS JOIN LATERAL (
    SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (
        SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
    )
) md;

SELECT o.recordvault, o.dealedge, o.dealcount, 
    (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (
        SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
    )) AS market_depth_details
FROM orders o;

SELECT DISTINCT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN orderexecutions oe ON o.recordvault = oe.ordersmark
CROSS JOIN (
    SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (
        SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
    )
) md;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o, marketdata md
WHERE md.marketdatanode = (
    SELECT ms.mdlink FROM marketstats ms WHERE ms.marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
)
AND (
    (o.dealedge = 'Sell' AND o.dealcount > 0.1 * (md.quote_depth_snapshot->'depth'->>'bidunits')::numeric)
    OR 
    (o.dealedge = 'Buy' AND o.dealcount > 0.1 * (md.quote_depth_snapshot->'depth'->>'askunits')::numeric)
);

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN marketdata md ON 1=1
WHERE md.marketdatanode = (
    SELECT ms.mdlink FROM marketstats ms WHERE ms.marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
);

SELECT o.recordvault, o.dealedge, o.dealcount, 
    (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (
        SELECT ms.mdlink FROM marketstats ms WHERE ms.marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
    )) AS market_depth_details
FROM orders o;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN marketdata md ON md.marketdatanode = (
    SELECT ms.mdlink FROM marketstats ms WHERE ms.marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
)
WHERE o.dealcount > 5;

SELECT recordvault, dealedge, dealcount, quote_depth_snapshot
FROM orders, marketdata
WHERE marketdatanode = (
    SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
);

SELECT o.recordvault, o.dealedge, o.dealcount, mds.quote_depth_snapshot
FROM orders o
JOIN (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = 1000) mds ON TRUE;

WITH latest_md AS (
    SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats))
)
SELECT o.recordvault, o.dealedge, o.dealcount, lmd.quote_depth_snapshot
FROM orders o, latest_md lmd;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN marketdata md ON md.marketdatanode = (SELECT MAX(marketdatanode) FROM marketdata);

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN marketdata md ON md.marketdatanode = (SELECT MAX(mdlink) FROM marketstats);

SELECT o.recordvault, o.dealedge, o.dealcount, 
    (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (SELECT mdlink FROM marketstats WHERE marketstatsmark = 1000)) AS market_depth_details
FROM orders o;

WITH latest_stats AS (
    SELECT mdlink FROM marketstats WHERE marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats)
),
latest_data AS (
    SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (SELECT mdlink FROM latest_stats)
)
SELECT o.recordvault, o.dealedge, o.dealcount, ld.quote_depth_snapshot
FROM orders o, latest_data ld;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o, 
    (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = (SELECT MAX(mdlink) FROM marketstats)) md;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN marketdata md ON md.marketdatanode = (SELECT ms.mdlink FROM marketstats ms WHERE ms.marketstatsmark = 1000);

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o, marketdata md, marketstats ms
WHERE md.marketdatanode = ms.mdlink AND ms.marketstatsmark = (SELECT MAX(marketstatsmark) FROM marketstats);

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o
JOIN (SELECT quote_depth_snapshot FROM marketdata WHERE marketdatanode = 1000) md ON 1=1;

SELECT o.recordvault, o.dealedge, o.dealcount, md.quote_depth_snapshot
FROM orders o, marketdata md
WHERE md.marketdatanode = 1000;

